#[test]
fn define_below_the_root_is_an_unknown_argument_naming_the_token() {
    let cases: &[(&[&str], &str)] = &[
        (
            &["tool", "serve", "--define", "a=1", "worker", "--port", "80"],
            "tool serve",
        ),
        (
