use clap::{Command, Arg, ArgAction};

fn build() -> Command {
    Command::new("tool")
        .arg(Arg::new("config").long("config").global(true).default_value("builtin.toml"))
        .arg(
            Arg::new("define")
                .long("define")
                .global(true)
                .action(ArgAction::Append),
        )
        .allow_external_subcommands(true)
        .subcommand(
            Command::new("serve")
                .allow_external_subcommands(true)
                .subcommand(
                    Command::new("worker")
                        .arg(Arg::new("port").long("port").required(true)),
                ),
        )
        .subcommand(Command::new("check"))
}

fn main() {
    let cases: Vec<Vec<&str>> = vec![
        vec!["tool", "--define", "a=1", "serve", "--define", "b=2", "worker", "--define", "c=3", "--port", "80"],
        vec!["tool", "serve", "--define", "b=2", "worker", "--port", "80", "--define", "c=3"],
        vec!["tool", "check", "--define", "z=9"],
    ];
    for argv in cases {
        match build().try_get_matches_from(&argv) {
            Ok(m) => {
                let root_def = m.get_many::<String>("define").map(|v| v.cloned().collect::<Vec<_>>());
                let mut cur = &m;
                let mut chain_defs = vec![];
                loop {
                    if let Some((n, sub)) = cur.subcommand() {
                        chain_defs.push((n.to_owned(), sub.get_many::<String>("define").map(|v| v.cloned().collect::<Vec<_>>())));
                        cur = sub;
                    } else { break; }
                }
                println!("{argv:?}\n  root={root_def:?}\n  chain={chain_defs:?}");
            }
            Err(e) => println!("{argv:?} => ERR {:?}: {}", e.kind(), e.to_string().lines().next().unwrap_or("")),
        }
    }
}
