use clap::{Command, Arg, ArgAction, value_parser};
use clap::error::ErrorKind;

fn parse_define(raw: &str) -> Result<(String,String), String> {
    let Some((k,v)) = raw.split_once('=') else { return Err(format!("invalid define `{raw}`: expected key=value")); };
    if v.contains('=') { return Err(format!("invalid define `{raw}`: multiple =")); }
    if k.is_empty() { return Err(format!("invalid define `{raw}`: empty key")); }
    if v.is_empty() { return Err(format!("invalid define `{raw}`: empty value")); }
    if k.chars().any(char::is_whitespace) || v.chars().any(char::is_whitespace) {
        return Err(format!("invalid define `{raw}`: whitespace"));
    }
    Ok((k.to_owned(), v.to_owned()))
}
fn parse_port(raw: &str) -> Result<u16,String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("invalid port `{raw}`"));
    }
    match raw.parse::<u32>() { Ok(p) if (1..=65535).contains(&p) => Ok(p as u16), _ => Err(format!("invalid port `{raw}`")) }
}

fn build() -> Command {
    Command::new("tool")
        .after_help("External plugins: any other <COMMAND> is captured as a root plugin.")
        .arg(Arg::new("config").long("config").global(true).default_value("builtin.toml").value_name("path"))
        .arg(Arg::new("define").long("define").global(true).value_name("key=value")
            .action(ArgAction::Append).value_parser(parse_define))
        .subcommand_required(true).arg_required_else_help(true)
        .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
        .subcommand(
            Command::new("serve").visible_alias("srv").alias("serve-hidden")
                .after_help("External plugins: any other <COMMAND> is captured as a serve plugin.")
                .subcommand_required(true).arg_required_else_help(true)
                .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
                .subcommand(
                    Command::new("worker").visible_alias("wkr").alias("worker-hidden")
                        .arg(Arg::new("port").long("port").required(true).value_parser(parse_port))
                        .arg(Arg::new("http").long("http").action(ArgAction::SetTrue).conflicts_with("https"))
                        .arg(Arg::new("https").long("https").action(ArgAction::SetTrue).conflicts_with("http"))
                        .arg(Arg::new("trailing").action(ArgAction::Append).num_args(1..).last(true)),
                ),
        )
        .subcommand(Command::new("check").visible_alias("chk").alias("check-hidden")
            .arg(Arg::new("path").action(ArgAction::Set))
            .arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)))
}

fn show(argv: &[&str]) {
    match build().try_get_matches_from(argv) {
        Ok(m) => {
            let defs = |x: &clap::ArgMatches| x.get_many::<(String,String)>("define").map(|v| v.cloned().collect::<Vec<_>>()).unwrap_or_default();
            println!("{argv:?} OK root_def={:?}", defs(&m));
            let mut cur = &m;
            while let Some((n,sub)) = cur.subcommand() {
                let ext = sub.get_many::<String>("").map(|v| v.cloned().collect::<Vec<_>>());
                println!("    {n} def={:?} ext={ext:?} port={:?}", defs(sub), sub.get_one::<u16>("port"));
                cur = sub;
            }
        }
        Err(e) => println!("{argv:?} ERR {:?}: {}", e.kind(), e.to_string().lines().take(4).collect::<Vec<_>>().join(" | ")),
    }
}

fn main() {
    show(&["tool","--define","a=1","serve","--define","b=2","worker","--define","c=3","--port","80"]);
    show(&["tool","srv","--define","=v","plug"]);               // invalid define at serve level
    show(&["tool","srv","wkr","--define","bad","--port","80"]); // invalid define at worker level
    show(&["tool","srv","wkr","--port","80","--define","x =1"]);// whitespace define deep
    show(&["tool","serve","plug","--define","=v"]);             // after plugin name => data
    show(&["tool","srv","plug","--define","=v"]);
    show(&["tool","--define","a=1","--define","b=2","srv","--define","c=3","wkr","--port","80","--define","d=4"]);
    show(&["tool","chk","--define","ok=1","--strict","p"]);
    // help through aliases
    if let Err(e) = build().try_get_matches_from(&["tool","srv","wkr","--help"]) {
        println!("HELP via alias kind={:?}", e.kind());
        assert_eq!(e.kind(), ErrorKind::DisplayHelp);
        println!("{}", e);
    }
