cat > examples/alias_probe.rs <<'EOF'
use clap::{Command, Arg, ArgAction, value_parser};
use clap::error::ErrorKind;

fn parse_define(raw: &str) -> Result<(String,String), String> {
    let Some((k,v)) = raw.split_once('=') else { return Err(format!("invalid define `{raw}`: expected key=value")); };
    if v.contains('=') { return Err(format!("invalid define `{raw}`: multiple =")); }
    if k.is_empty() { return Err(format!("invalid define `{raw}`: empty key")); }
    if v.is_empty() { return Err(format!("invalid define `{raw}`: empty value")); }
    if k.chars().any(char::is_whitespace) || v.chars().any(char::is_whitespace) { return Err(format!("invalid define `{raw}`: whitespace")); }
    Ok((k.to_owned(), v.to_owned()))
}
fn parse_port(raw: &str) -> Result<u16,String> {
    if raw.is_empty() || !raw.bytes().all(|b| b.is_ascii_digit()) { return Err(format!("invalid port `{raw}`")); }
    match raw.parse::<u32>() { Ok(p) if (1..=65535).contains(&p) => Ok(p as u16), _ => Err(format!("invalid port `{raw}`")) }
}

fn build() -> Command {
    Command::new("tool")
        .arg(Arg::new("config").long("config").global(true).default_value("builtin.toml").value_name("path"))
        // root-scoped (NOT global) repeatable define, like task018
        .arg(Arg::new("define").long("define").value_name("key=value")
            .action(ArgAction::Append).value_parser(parse_define))
        .subcommand_required(true).arg_required_else_help(true)
        .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
        .subcommand(
            Command::new("serve").visible_alias("srv").alias("serve-hidden")
                .subcommand_required(true).arg_required_else_help(true)
                .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
                .subcommand(
                    Command::new("worker").visible_alias("wkr").alias("worker-hidden")
                        .arg(Arg::new("port").long("port").required(true).value_parser(parse_port))
                        .arg(Arg::new("http").long("http").action(ArgAction::SetTrue).conflicts_with("https"))
                        .arg(Arg::new("https").long("https").action(ArgAction::SetTrue).conflicts_with("http"))
                        .arg(Arg::new("trailing").action(ArgAction::Append).num_args(1..).last(true)),
                ),
        )
        .subcommand(Command::new("check").visible_alias("chk").alias("check-hidden")
            .arg(Arg::new("path").action(ArgAction::Set))
            .arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)))
}

fn show(argv: &[&str]) {
    match build().try_get_matches_from(argv) {
        Ok(_) => println!("{argv:?} OK"),
        Err(e) => {
            let usage = e.to_string().lines().filter(|l| l.starts_with("Usage:")).next().unwrap_or("");
            println!("{argv:?} ERR {:?} | {usage}", e.kind());
        }
    }
}

fn main() {
    // define through aliases at root: works
    show(&["tool","--define","a=1","srv","wkr","--port","80"]);
    // wrong-level define THROUGH ALIASES -> UnknownArgument naming canonical command
    show(&["tool","srv","--define","a=1","plug"]);
    show(&["tool","srv","wkr","--port","80","--define","a=1"]);
    show(&["tool","chk","--define","a=1"]);
    // positional swap: config straddling alias tokens
    show(&["tool","--config","c","srv","--config","d","wkr","--port","80","--config","e"]);
    // missing port through aliases -> MissingRequiredArgument canonical usage
    show(&["tool","srv","wkr"]);
    // duplicate port through aliases
    show(&["tool","srv","wkr","--port","80","--port","90"]);
    // invalid define classes through alias chain
    for raw in ["", "=", "=v", "k=", "a=b=c", "novalue", " a=b", "a=b "] {
        show(&["tool","--define",raw,"chk"]);
    }
    // external at serve after root plugin name token colliding with alias
    show(&["tool","plug","srv","wkr"]);
    show(&["tool","srv","plug","wkr","--port"]);
    // help via aliases
    for a in [["tool","srv","--help"][..].to_vec(), vec!["tool","srv","wkr","--help"], vec!["tool","chk","--help"]] {
        let r = build().try_get_matches_from(&a);
        println!("{a:?} => {:?}", r.as_ref().map(|_|()).map_err(|e| e.kind()));
    }
    let _ = ErrorKind::DisplayHelp;
}
EOF
