use clap::{Command, Arg, ArgAction, value_parser};

fn build() -> Command {
    Command::new("tool")
        .after_help("External plugins: any other <COMMAND> is captured as a root plugin.")
        .arg(Arg::new("config").long("config").global(true).default_value("builtin.toml").value_name("path"))
        .arg(Arg::new("define").long("define").value_name("key=value").action(ArgAction::Append))
        .subcommand_required(true).arg_required_else_help(true)
        .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
        .subcommand(Command::new("serve").visible_alias("srv").alias("serve-hidden")
            .after_help("External plugins: any other <COMMAND> is captured as a serve plugin.")
            .subcommand_required(true).arg_required_else_help(true)
            .allow_external_subcommands(true).external_subcommand_value_parser(value_parser!(String))
            .subcommand(Command::new("worker").visible_alias("wkr").alias("worker-hidden")
                .arg(Arg::new("port").long("port").required(true))
                .arg(Arg::new("http").long("http").action(ArgAction::SetTrue).conflicts_with("https"))
                .arg(Arg::new("https").long("https").action(ArgAction::SetTrue).conflicts_with("http"))
                .arg(Arg::new("trailing").action(ArgAction::Append).num_args(1..).last(true))))
        .subcommand(Command::new("check").visible_alias("chk").alias("check-hidden")
            .arg(Arg::new("path")).arg(Arg::new("strict").long("strict").action(ArgAction::SetTrue)))
}
fn help(argv: &[&str]) -> String { build().try_get_matches_from(argv).err().unwrap().to_string() }
fn main() {
    let pairs = [
        (&["tool","serve","--help"][..], &["tool","srv","--help"][..]),
        (&["tool","serve","worker","--help"][..], &["tool","srv","wkr","--help"][..]),
        (&["tool","check","--help"][..], &["tool","chk","--help"][..]),
    ];
    for (a,b) in pairs {
        let (ha,hb) = (help(a), help(b));
        println!("{a:?} vs {b:?} identical={}", ha==hb);
    }
    // missing subcommand through alias
    let e = build().try_get_matches_from(&["tool","srv"]).err().unwrap();
    println!("tool srv -> kind={:?}", e.kind());
    // hidden aliases absent, visible present
    let h = help(&["tool","--help"]);
    println!("root help has srv={} serve-hidden={} chk={} check-hidden={}", h.contains("srv"), h.contains("serve-hidden"), h.contains("chk"), h.contains("check-hidden"));
    let h = help(&["tool","serve","--help"]);
    println!("serve help has wkr={} worker-hidden={}", h.contains("wkr"), h.contains("worker-hidden"));
    println!("--- root help ---\n{h}");
}
EOF
