        serve_external_ok(&["tool", "serve", "work", "x"]).tokens,
        vec!["work", "x"]
    );
    // `check` is declared at the root only, so under `serve` it is a plugin.
    assert_eq!(
        serve_external_ok(&["tool", "serve", "check"]).tokens,
